import subprocess

def check_pdftotext():
    try:
        result = subprocess.run(['pdftotext', '-v'], capture_output=True, text=True)
        print("pdftotext version:", result.stdout)
    except FileNotFoundError:
        print("pdftotext is not installed or not found in PATH.")
    except Exception as e:
        print("An error occurred:", str(e))

check_pdftotext()
